$headers = @{ "Accept"="application/json, text/event-stream"; "Content-Type"="application/json"; "MCP-Protocol-Version"="2024-11-05" }
# initialize first
$init = '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"probe","version":"0"}}}'
try {
  $r = Invoke-WebRequest -Uri "http://127.0.0.1:1933/mcp" -Method Post -Headers $headers -Body $init -TimeoutSec 8 -UseBasicParsing
  "init status=$($r.StatusCode)"
  $sid = $r.Headers['Mcp-Session-Id']; "session=$sid"
  if($sid){ $headers['Mcp-Session-Id']=$sid }
  $tl = '{"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}}'
  $r2 = Invoke-WebRequest -Uri "http://127.0.0.1:1933/mcp" -Method Post -Headers $headers -Body $tl -TimeoutSec 8 -UseBasicParsing
  $content = $r2.Content
  # may be SSE "data: {...}"
  $json = ($content -split "`n" | Where-Object { $_ -match '^data:' } | Select-Object -First 1)
  if($json){ $json = $json -replace '^data:\s*','' } else { $json = $content }
  $obj = $json | ConvertFrom-Json
  $tools = $obj.result.tools
  "TOOL_COUNT=$($tools.Count)"
  $tot=0; $tools | ForEach-Object { $s=($_ | ConvertTo-Json -Depth 12 -Compress); $tot += [Text.Encoding]::UTF8.GetByteCount($s) }
  "TOTAL_JSON_BYTES=$tot"
  $tools | ForEach-Object { $s=($_ | ConvertTo-Json -Depth 12 -Compress); "{0,-24} {1}" -f $_.name, [Text.Encoding]::UTF8.GetByteCount($s) } | Sort-Object
} catch { "err: $($_.Exception.Message)" }
